class User {
  public function __construct(public string $name) {}
  public function greet(): string {
    return 'Hello, ' . $this->name;
  }
}
$user = new User('Pomo');

class Base {
  public function greet(): string {
    return 'Hello';
  }
}
class Child extends Base {
  public function greet(): string {
    return parent::greet() . '!';
  }
}

interface Greeter {
  public function greet(): string;
}
class Bot implements Greeter {
  public function greet(): string {
    return 'Hi';
  }
}

class MathUtil {
  public static function twice(int $n): int {
    return $n * 2;
  }
}
echo MathUtil::twice(2);

try {
  throw new RuntimeException('失敗');
} catch (Throwable $e) {
  echo $e->getMessage();
} finally {
  echo '終了';
}

function numbers(): Generator {
  for ($i = 0; $i < 3; $i++) {
    yield $i;
  }
}
foreach (numbers() as $n) {
  echo $n;
}
